<section class="card" id="statements"><div class="card-header"><div><span class="section-kicker">Classificazione piano dei conti</span><h2>Stato patrimoniale e conto economico <?= $year ?></h2><p class="help">Periodo <?= View::date($periodStart->format('Y-m-d')) ?> – <?= View::date($periodEnd->format('Y-m-d')) ?>. I saldi sono esposti secondo la natura Dare/Avere e raggruppati dalla sezione configurata sul conto.</p></div></div><div class="statement-summary"><?php foreach ($statementTotals as $section => $amount): ?><article><span><?= View::e($section) ?></span><strong><?= View::money($amount) ?></strong></article><?php endforeach; ?></div><div class="table-wrap"><table><thead><tr><th>Sezione</th><th>Codice</th><th>Conto</th><th>Tipo</th><th>Dare</th><th>Avere</th><th>Saldo esposto</th></tr></thead><tbody><?php foreach ($statements as $row): ?><tr><td><?= View::e($row['statement_section']) ?></td><td><?= View::e($row['code']) ?></td><td class="primary-cell"><?= View::e($row['name']) ?></td><td><?= View::e($row['account_type']) ?></td><td><?= View::money($row['debit']) ?></td><td><?= View::money($row['credit']) ?></td><td class="primary-cell"><?= View::money($row['display_balance']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>

