<section class="card" id="closing"><div class="card-header"><div><span class="section-kicker">Procedura irreversibile senza storno</span><h2>Chiusura e apertura esercizio</h2><p class="help">Il sistema controlla bozze e quadratura, chiude i conti economici, riporta il risultato e genera l’apertura.</p></div><form method="post" action="/accounting/compliance/closings" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><input type="number" name="year" min="2000" max="2200" value="<?= $year ?>"><button class="button primary" type="submit">Prepara controlli</button></form></div><div class="table-wrap"><table><thead><tr><th>Esercizio</th><th>Risultato</th><th>Controlli</th><th>Stato</th><th>Registrazioni</th><th></th></tr></thead><tbody><?php foreach ($closingRuns as $row): $validation = json_decode((string) $row['validation_json'], true) ?: []; ?><tr><td class="primary-cell"><?= (int) $row['fiscal_year'] ?></td><td><?= View::money($row['profit_loss_amount']) ?></td><td><span class="badge status-<?= !empty($validation['valid']) ? 'active' : 'error' ?>"><?= !empty($validation['valid']) ? 'SUPERATI' : count($validation['errors'] ?? []) . ' ERRORI' ?></span></td><td><?= View::e($row['status']) ?></td><td><?= $row['closing_journal_entry_id'] ? '#' . (int) $row['closing_journal_entry_id'] . ' / #' . (int) $row['opening_journal_entry_id'] : '—' ?></td><td><?php if (!empty($validation['valid']) && $row['status'] !== 'POSTED'): ?><form method="post" action="/accounting/compliance/closings/<?= (int) $row['id'] ?>/post"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="year" value="<?= (int) $row['fiscal_year'] ?>"><button class="button danger" type="submit">Contabilizza chiusura</button></form><?php elseif (empty($validation['valid'])): ?><small class="danger-text"><?= View::e(implode(' · ', $validation['errors'] ?? [])) ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>

